import Foundation

// MARK: - Model

/// One step of an alarm, generated by the engine from an `alarms:` entry.
public enum AlarmStep: Sendable {
    /// Switch on every Hue light in the house that is off (except in `exceptRooms`) and turn the accent lights `accentColor`.
    case start(exceptRooms: [String], accentLights: [String], accentColor: String, brightness: Double)
    /// Undo `start`: switch off what it switched on, put the accent lights back to white (and off if they were off).
    case end(accentLights: [String], kelvin: Int)
    /// Switches a Lutron switch on or off (extra coverage the Hue rooms don't give, e.g. garage and outdoor spots).
    case lutron(device: String, on: Bool)
    /// Starts a macOS Shortcut (e.g. one that plays a sound on the HomePods). Returns without waiting for it to finish.
    case soundStart(shortcut: String)
    /// Runs the optional stop Shortcut and ends the start one if it is still running.
    case soundStop(started: String, stop: String?)
}

/// "Someone is at the house and nobody is home": lights, a red accent light and a sound, until `keepSeconds`
/// after the last detection. Does not start while any presence hold is active.
public struct Alarm: Sendable {
    public var name: String
    public var enabled = true
    /// UniFi detections (device + event such as `person`); `start` begins or extends, `end` lets the countdown run.
    public var triggers: [TriggerSpec]
    public var keepSeconds: TimeInterval
    /// Safety net: end even if no `end` notification arrives (e.g. a dropped connection) this long after the last one.
    public var maxSeconds: TimeInterval
    public var exceptRooms: [String]
    public var brightness: Double
    public var lutronSwitches: [String]
    public var accentLights: [String]
    public var accentColor: String
    public var normalKelvin: Int
    public var soundStart: String?
    public var soundStop: String?

    var startSteps: [AlarmStep] {
        var steps: [AlarmStep] = [.start(exceptRooms: exceptRooms, accentLights: accentLights, accentColor: accentColor, brightness: brightness)]
        steps += lutronSwitches.map { .lutron(device: $0, on: true) }
        if let soundStart { steps.append(.soundStart(shortcut: soundStart)) }
        return steps
    }

    var endSteps: [AlarmStep] {
        var steps: [AlarmStep] = []
        if let soundStart { steps.append(.soundStop(started: soundStart, stop: soundStop)) }
        // Off regardless of how they were: their own motion rules would switch them off after a few minutes anyway.
        steps += lutronSwitches.map { .lutron(device: $0, on: false) }
        steps.append(.end(accentLights: accentLights, kelvin: normalKelvin))
        return steps
    }

    func matches(_ event: TriggerEvent) -> Bool {
        (event.kind == "start" || event.kind == "end") && triggers.contains { $0.matches(event, ignoringKind: true) }
    }
}

// MARK: - Parsing

extension ConfigLoader {
    static func parseAlarm(_ r: Reader) throws -> Alarm {
        try r.rejectUnknown(["name", "enabled", "when", "keep_seconds", "max_minutes", "lights", "accent", "sound", "normal_color_temp_kelvin"])
        guard case .array(let rawWhen)? = r.map["when"], !rawWhen.isEmpty else {
            throw ConfigError(path: r.path + ".when", message: "needs a non-empty list, e.g. - { unifi: Front Camera, event: person }")
        }
        var triggers: [TriggerSpec] = []
        for (i, raw) in rawWhen.enumerated() {
            guard case .map(let m) = raw else { throw ConfigError(path: "\(r.path).when[\(i)]", message: "must be a map") }
            let reader = Reader(map: m, path: "\(r.path).when[\(i)]")
            guard m["unifi"] != nil, m["event"] != nil else {
                throw ConfigError(path: reader.path, message: "must name a camera and a detection, e.g. { unifi: Front Camera, event: person }")
            }
            try reader.rejectUnknown(["unifi", "event"])
            triggers.append(try parseTrigger(reader))
        }
        let keep = try r.double("keep_seconds") ?? 30
        guard keep > 0 else { throw ConfigError(path: r.path + ".keep_seconds", message: "must be greater than 0") }
        let maxMinutes = try r.double("max_minutes") ?? 10
        guard maxMinutes * 60 >= keep else { throw ConfigError(path: r.path + ".max_minutes", message: "must be at least keep_seconds") }

        var except: [String] = [], lutronSwitches: [String] = [], brightness = 100.0
        if let l = try r.reader("lights") {
            try l.rejectUnknown(["except_rooms", "brightness", "lutron"])
            except = try l.stringList("except_rooms")
            lutronSwitches = try l.stringList("lutron")
            brightness = try l.double("brightness") ?? 100
            guard (1...100).contains(brightness) else { throw ConfigError(path: l.path + ".brightness", message: "must be 1–100") }
        }
        var accent: [String] = [], color = "#FF0000"
        if let a = try r.reader("accent") {
            try a.rejectUnknown(["lights", "color"])
            accent = try a.stringList("lights")
            color = try a.string("color") ?? color
            guard ColorMath.xy(fromHex: color) != nil else { throw ConfigError(path: a.path + ".color", message: "expected a hex color like \"#FF0000\"") }
        }
        var start: String?, stop: String?
        if let s = try r.reader("sound") {
            try s.rejectUnknown(["start", "stop"])
            start = try s.requireString("start")
            stop = try s.string("stop")
        }
        let kelvin = try r.int("normal_color_temp_kelvin") ?? 2700
        guard (2000...6500).contains(kelvin) else { throw ConfigError(path: r.path + ".normal_color_temp_kelvin", message: "must be 2000–6500") }
        return Alarm(name: try r.requireString("name"), enabled: try r.bool("enabled") ?? true, triggers: triggers,
                     keepSeconds: keep, maxSeconds: maxMinutes * 60, exceptRooms: except, brightness: brightness,
                     lutronSwitches: lutronSwitches, accentLights: accent, accentColor: color, normalKelvin: kelvin, soundStart: start, soundStop: stop)
    }
}

// MARK: - Shortcuts

/// Runs macOS Shortcuts through `/usr/bin/shortcuts`. This is how a sound gets to the HomePods: a Shortcut can pick
/// them as the playback destination, which nothing else available to a background app can do. Arguments are passed
/// without a shell, so names can't inject commands.
public final class ShortcutRunner: @unchecked Sendable {
    private let log: @Sendable (LogEntry) -> Void
    private let lock = NSLock()
    private var running: [String: Process] = [:]

    public init(log: @escaping @Sendable (LogEntry) -> Void) { self.log = log }

    private func make(_ name: String) -> Process {
        let p = Process()
        p.executableURL = URL(fileURLWithPath: "/usr/bin/shortcuts")
        p.arguments = ["run", name]
        p.standardOutput = FileHandle.nullDevice
        let err = Pipe()
        p.standardError = err
        p.terminationHandler = { [weak self] proc in
            self?.lock.withLock { if self?.running[name] === proc { self?.running[name] = nil } }
            guard proc.terminationReason == .exit, proc.terminationStatus != 0 else { return }
            let text = String(data: err.fileHandleForReading.availableData, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            self?.log(LogEntry(level: .error, category: "shortcuts", message: "‘\(name)’ exited with \(proc.terminationStatus)\(text.isEmpty ? "" : ": \(text)")"))
        }
        return p
    }

    /// Starts `name` and returns at once; the Shortcut keeps running (a looping sound) until it finishes or `stop` is called.
    public func start(_ name: String) throws {
        if lock.withLock({ running[name]?.isRunning == true }) { return }
        let p = make(name)
        try p.run()
        lock.withLock { running[name] = p }
        log(LogEntry(category: "shortcuts", message: "started ‘\(name)’"))
    }

    /// Runs the `stop` Shortcut (if any) to completion, then ends `started` if it is still running.
    public func stop(started: String, stop: String?) async {
        if let stop {
            let p = make(stop)
            do {
                try p.run()
                log(LogEntry(category: "shortcuts", message: "ran ‘\(stop)’"))
                for _ in 0..<300 where p.isRunning { try? await Task.sleep(for: .milliseconds(100)) }   // up to 30 s
                if p.isRunning { p.terminate() }
            } catch { log(LogEntry(level: .error, category: "shortcuts", message: "‘\(stop)’ failed: \(error)")) }
        }
        if let p = lock.withLock({ running.removeValue(forKey: started) }), p.isRunning { p.terminate() }
    }
}
